# ruff: noqa: F401

from logging import Logger
from os import path
from typing import List, Optional

from moler.config import load_config
from moler.device import DeviceFactory
from ta_moler.device.air_scale import AirScale

from ta_tti_collector import get_tts_path
from ta_tti_collector.utils import get_simple_logger, run_remote_cmd


class CellMapping(object):
    """Fetch cell mapping from eNB."""
    def __init__(self, host, logger=None):
        # type: (str, Optional[Logger]) -> None
        """
        Collect cell mapping and master_nid from eNB

        :param host: IP address of eNB
        :param logger:
        """
        self.logger = get_simple_logger(logger=logger, logger_name='tti_collector', stream=True,
                                        full_path=path.join(get_tts_path(name='server', enb='1'),
                                                            'ta_tti_collector.log'))
        self.process = 'RROMexe'
        self.host = host
        self.node = ''
        self._master_nid = ''
        self._cell_mapping = []
        try:
            self.aashell_device = self._get_aashell_device()
        except Exception:
            self.logger.exception('Cannot get device for {}'.format(self.host))
            raise

    def __call__(self, *args, **kwargs):
        self.node, self._master_nid = self._get_node_and_masternid_with_running_process()
        self._cell_mapping = self._get_cell_to_core_address_mapping()
        self._kill_telnet_connection()
        return self

    def __del__(self):
        """
        Close Telnet and all other connections made by moler.
        Telnet likes to hang after fetching cell mapping.
        """
        DeviceFactory.remove_all_devices()
        self._kill_telnet_connection()

    @property
    def cell_mapping(self):
        # type: () -> List[dict]
        """
        Returns cell mapping from eNB.

        :return: List[dict] with cell mapping
        """
        return self._cell_mapping

    @property
    def master_nid(self):
        # type: () -> str
        """
        Return master_nid.

        :return: str
        """
        return self._master_nid

    def _get_node_and_masternid_with_running_process(self):
        # type: () -> (str, str)
        """
        Search through Nodes for Node and master_nid with running process.
        Return first Node information and master_nid

        :return: str
        """
        nodes_output = self.aashell_device.get_cmd(cmd_name='nodes',
                                                   cmd_params={'options': '-p', 'process': self.process})()

        self.logger.debug('Output from Aashell nodes cmd {}'.format(nodes_output))

        node_and_master_nid = [(node, params['masterNid']) for (node, params) in nodes_output.items()
                               if self.process in params['processes']]
        node = node_and_master_nid[0][0]
        master_nid = node_and_master_nid[0][1]
        self.logger.debug('Selected first match node {} and masterNid {} with running process {}'
                          .format(node, master_nid, self.process))
        return node, master_nid

    def _get_cell_to_core_address_mapping(self):
        # type: () -> List[dict]
        params = '@' + self.process + ' #' + self.node
        cell_mapping = self.aashell_device.get_cmd(cmd_name='get_cell_mapping', cmd_params={'options': params})()
        self.logger.debug('Output from Aashell getCellMapping: {}'.format(cell_mapping))
        return cell_mapping

    def _get_device_in_state(self, state='FCT'):
        # type: (str) -> AirScale
        device = DeviceFactory.get_device(self.host)
        device.goto_state(state=state, timeout=3)
        return device

    def _get_aashell_device(self):
        # type: () -> AirScale
        try:
            load_config(config=self._fill_cfg())
        except Exception as e:
            self.logger.debug('[Error] Moler exception: {} '.format(e))
        device = self._get_device_in_state(state='FCT')
        self._kill_telnet_connection()
        device.goto_state(state='AASHELL', timeout=3)
        return device

    def _kill_telnet_connection(self):
        # type: () -> None
        enb_data = {'user': 'toor4nsn', 'host': self.host, 'passwd': 'oZPS0POrRieRtu'}
        pkill_telnet = 'pkill -f "telnet localhost 15007"'
        run_remote_cmd(logger=self.logger, cmd=pkill_telnet, timeout=3, **enb_data)

    def _fill_cfg(self):
        # type: () -> dict
        return {
            'DEVICES': {
                self.host: {
                    'DEVICE_CLASS': 'ta_moler.device.air_scale.AirScale',
                    'INITIAL_STATE': 'UNIX_LOCAL',
                    'CONNECTION_HOPS': {
                        'UNIX_LOCAL': {'FCT': {'execute_command': 'ssh',
                                               'command_params': {
                                                   'host': self.host,
                                                   'set_timeout': None}}},
                        'FCT': {'AASHELL': {'execute_command': 'telnet',
                                            'command_params': {'host': 'localhost',
                                                               'port': 15007,
                                                               'set_timeout': None}}}}}}}
